sys_relationship.query_with:
(function refineQuery(current, parent) {
	var site = parent.getValue('x_g_sonc_ns_pro_site');
	var priSec = parent.getValue('x_g_sonc_ns_pro_pri_sec_circuit');
	var parentSysID = parent.getValue('sys_id');
	var hostCircuit = parent.getValue('x_g_sonc_ns_pro_pending_pe_host_circuit_id');

	var queryString = "site=" + site + "^pending_local_circuit_id.sys_id=" + parentSysID + "^x_g_sonc_ns_pro_pri_sec_circuit=" + priSec;
	if(hostCircuit){
		queryString = queryString + "^pending_pe_host_circuit_id=" + hostCircuit;
	}

	current.addEncodedQuery(queryString);

})(current, parent);
